"""
    This method is used to construct the path from start edge to goal edge
    """
def _reconstruct_path(came_from: Any, start: Any, goal: Any) -> object {
    current = goal;
    path = [];
    while (current != start) {
        path.append(current);
        current = came_from.get(current);
    }
    path.append(start);
    path.reverse();
    return path;
}

"""Returns the first non-null element of the iterable.

    If there is no non-null elements in the iterable--or the iterable is
    empty--the default value is returned.

    If the value to be returned is an exception object, it is raised instead.
    """
def icoalesce(iterable: Any, `default: Any = None) -> object {
    result = next(
        (
            i
            for i in iterable
            if (i is not None)
        ),
        `default
    );
    if isinstance(result, Exception) {
        raise result;
    }
    return result;
}

"""n-Significant Figures"""
def nsf(num: Any, n: Any = 1) -> object {
    while ((n - 1) < 0) {
        n += 1;
    }
    numstr = ("{0:.%ie}" % (n - 1)).format(num);
    return float(numstr);
}

